inline const TemplatePolicy* FindTemplatePolicy(uint64_t a,uint64_t b){
 const auto end=templatePolicies+sizeof(templatePolicies)/sizeof(templatePolicies[0]);
 const auto p=std::lower_bound(templatePolicies,end,std::pair<uint64_t,uint64_t>{a,b},[](const TemplatePolicy& row,const std::pair<uint64_t,uint64_t>& key){return row.a<key.first||(row.a==key.first&&row.b<key.second);});
 return p!=end&&p->a==a&&p->b==b?p:nullptr;
}
